function showToast(message,type = 'success',delay = 3000){const toastContainer = document.getElementById('toastContainer');if(!toastContainer)return;const toast = document.createElement('div');toast.className = `toast align-items-center text-white bg-${type}border-0 position-fixed end-0 m-3`;toast.setAttribute('role','alert');toast.setAttribute('aria-live','assertive');toast.setAttribute('aria-atomic','true');toast.style.zIndex = '1060';toast.innerHTML = ` <div class="d-flex"> <div class="toast-body">${message}</div> <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Close"></button> </div> `;const visibleToasts = document.querySelectorAll('.toast.show');const toastHeight = 60;const bottomOffset = visibleToasts.length * toastHeight + 10;toast.style.bottom = `${bottomOffset}px`;toastContainer.appendChild(toast);const bootstrapToast = new bootstrap.Toast(toast,{delay});bootstrapToast.show();toast.addEventListener('hidden.bs.toast',()=>{toast.remove();const remainingToasts = document.querySelectorAll('.toast.show');remainingToasts.forEach((t,index)=>{t.style.bottom = `${index * toastHeight + 10}px`;});});}function showConfirm(message,type = 'primary',title = '确认操作'){return new Promise((resolve)=>{const modalId = 'dynamicConfirmModal';const modalContainer = document.createElement('div');modalContainer.className = 'modal fade';modalContainer.id = modalId;modalContainer.setAttribute('tabindex','-1');modalContainer.style.zIndex = '1070';const iconMap ={danger:'<i class="fas fa-exclamation-circle text-danger me-2"></i>',warning:'<i class="fas fa-exclamation-triangle text-warning me-2"></i>',primary:'<i class="fas fa-info-circle text-primary me-2"></i>'};modalContainer.innerHTML = ` <div class="modal-dialog modal-dialog-centered modal-sm"> <div class="modal-content shadow border-0"> <div class="modal-header border-0 pb-0"> <h5 class="modal-title" style="font-size:1.1rem;font-weight:600;"> ${iconMap[type]|| ''}${title}</h5> <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button> </div> <div class="modal-body py-3 text-secondary"> ${message}</div> <div class="modal-footer border-0 pt-0"> <button type="button" class="btn btn-light btn-sm px-3" data-bs-dismiss="modal">取消</button> <button type="button" class="btn btn-${type}btn-sm px-3" id="confirmActionBtn">确认</button> </div> </div> </div> `;document.body.appendChild(modalContainer);const bsModal = new bootstrap.Modal(modalContainer);const confirmBtn = modalContainer.querySelector('#confirmActionBtn');confirmBtn.onclick =()=>{bsModal.hide();resolve(true);};modalContainer.addEventListener('hidden.bs.modal',()=>{resolve(false);modalContainer.remove();});bsModal.show();});}